-- fase83_jce_juntas_2026.sql · Resolución JCE No. 08-2026 (integración preliminar de las 162 juntas electorales)
-- Idempotente. Esquema public (compartido con Análisis Electoral).
--
-- Origen: certificación de la Resolución 08-2026 del 29 sep 2026 (54 páginas escaneadas),
-- leída por OCR y validada: 162 juntas, 1,476 cargos (9 por junta; 15 en Distrito Nacional,
-- Santiago y Santo Domingo Este), dígito verificador correcto en las 1,476 cédulas, sin
-- cédulas repetidas, secuencia de cargos coherente en todas las juntas.
--
-- Qué hace: 1) tabla public.jce_juntas_2026 con los 1,476 cargos; 2) empareja cada junta con
-- public.municipios (junta_nombre / nombre); 3) trae el nombre oficial del padrón por cédula;
-- 4) empareja cada persona con public.aspirantes por nombre dentro del municipio, en dos pasadas
-- (nombre completo; apellidos + primer nombre). Todo se puede repetir sin duplicar.

create table if not exists public.jce_juntas_2026 (
  junta          integer not null,
  municipio_jce  text    not null,
  orden          integer not null,
  cedula         text    not null,
  cedula_fmt     text    not null,
  nombre         text    not null,           -- tal como lo leyó el OCR
  cargo          text    not null,           -- nombres de cargo de Análisis Electoral (SEL_CARGOS_JUNTA)
  titular        boolean generated always as (cargo in ('Presidente','Primer Vocal','Segundo Vocal','Tercer Vocal','Cuarto Vocal')) stored,
  municipio_id   integer references public.municipios(id),
  nombre_padron  text,
  aspirante_id   bigint,
  partido_id     integer,
  match_tipo     text,                       -- 'nombre_completo' | 'apellidos_primer_nombre' | null
  fuente         text not null default 'Resolución JCE 08-2026 · 29 sep 2026',
  cargado_en     timestamptz not null default now(),
  primary key (junta, orden),
  unique (cedula)
);
create index if not exists jce_juntas_2026_mun_idx on public.jce_juntas_2026 (municipio_id);
alter table public.jce_juntas_2026 enable row level security;
drop policy if exists jj_lee on public.jce_juntas_2026;
create policy jj_lee on public.jce_juntas_2026 for select to authenticated using (true);
grant select on public.jce_juntas_2026 to authenticated;

on conflict (junta, orden) do nothing;

-- ── Normalizador de texto: mayúsculas, sin acentos, solo letras y números, un espacio ──
create or replace function public._norm_txt(t text) returns text
language sql immutable as $$
  select btrim(regexp_replace(regexp_replace(upper(translate(coalesce(t,''),
         'ÁÉÍÓÚÜÑáéíóúüñÀÈÌÒÙàèìòùÂÊÎÔÛâêîôûÄËÏÖäëïö', 'AEIOUUNAEIOUUNAEIOUAEIOUAEIOUAEIOUAEIOAEIO')),
         '[^A-Z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))
$$;

-- ── 2. Junta → municipio: primero por junta_nombre, luego por nombre (sin el paréntesis del OCR) ──
update public.jce_juntas_2026 j
   set municipio_id = m.id
  from public.municipios m
 where j.municipio_id is null and coalesce(m.estatus, 'A') <> 'I'
   and public._norm_txt(m.junta_nombre) in (public._norm_txt(j.municipio_jce),
                                            public._norm_txt(regexp_replace(j.municipio_jce, '\s*\(.*\)\s*', '', 'g')));

update public.jce_juntas_2026 j
   set municipio_id = m.id
  from public.municipios m
 where j.municipio_id is null and coalesce(m.estatus, 'A') <> 'I'
   and public._norm_txt(m.nombre) in (public._norm_txt(j.municipio_jce),
                                      public._norm_txt(regexp_replace(j.municipio_jce, '\s*\(.*\)\s*', '', 'g')));

-- ── 3. Nombre oficial del padrón por cédula (las dos escrituras posibles de la cédula) ──
update public.jce_juntas_2026 j
   set nombre_padron = btrim(concat_ws(' ', pa.nombres, pa.apellido1, pa.apellido2))
  from public.jce_padron pa
 where j.nombre_padron is null
   and (pa.cedula = j.cedula or pa.cedula = j.cedula_fmt);

-- ── 4a. Aspirante por nombre completo dentro del municipio (nombre del padrón o del OCR) ──
update public.jce_juntas_2026 j
   set aspirante_id = a.id, partido_id = a.partido_id, match_tipo = 'nombre_completo'
  from public.aspirantes a
 where j.aspirante_id is null and j.municipio_id is not null
   and a.municipio_id = j.municipio_id and a.activo
   and public._norm_txt(concat_ws(' ', a.nombres, a.apellido1, a.apellido2))
       in (public._norm_txt(j.nombre_padron), public._norm_txt(j.nombre));

-- ── 4b. Aspirante por apellidos del padrón + primer nombre, dentro del municipio ──
update public.jce_juntas_2026 j
   set aspirante_id = a.id, partido_id = a.partido_id, match_tipo = 'apellidos_primer_nombre'
  from public.aspirantes a, public.jce_padron pa
 where j.aspirante_id is null and j.municipio_id is not null
   and (pa.cedula = j.cedula or pa.cedula = j.cedula_fmt)
   and a.municipio_id = j.municipio_id and a.activo
   and public._norm_txt(concat_ws(' ', a.apellido1, a.apellido2)) = public._norm_txt(concat_ws(' ', pa.apellido1, pa.apellido2))
   and split_part(public._norm_txt(a.nombres), ' ', 1) = split_part(public._norm_txt(pa.nombres), ' ', 1);

-- ── 4c. Sin padrón: primer apellido (penúltima palabra del OCR) + primer nombre, dentro del municipio ──
update public.jce_juntas_2026 j
   set aspirante_id = a.id, partido_id = a.partido_id, match_tipo = 'ocr_apellido_primer_nombre'
  from public.aspirantes a
 where j.aspirante_id is null and j.municipio_id is not null and j.nombre_padron is null
   and a.municipio_id = j.municipio_id and a.activo
   and public._norm_txt(a.apellido1) = any (string_to_array(public._norm_txt(j.nombre), ' '))
   and split_part(public._norm_txt(a.nombres), ' ', 1) = split_part(public._norm_txt(j.nombre), ' ', 1);

-- Comprobación. Esperado: cargos = 1476, juntas = 162; los demás dicen cuánto quedó emparejado.
select count(*) as cargos, count(distinct junta) as juntas,
       count(distinct junta) filter (where municipio_id is not null) as juntas_con_municipio,
       count(*) filter (where nombre_padron is not null) as con_padron,
       count(*) filter (where aspirante_id is not null) as con_aspirante,
       count(*) filter (where partido_id is not null) as con_partido
  from public.jce_juntas_2026;
